103	     * from the postcode in preference to the city: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
104	     */
105	    private static final Map<String, int[]> REGION_POSTCODE = Map.of(
106	        "NSW", new int[] {2000, 2099},
107	        "VIC", new int[] {3000, 3099},
108	        "QLD", new int[] {4000, 4099});
109	
110	    public String getAddress() {
111	        return this.address;
112	    }
