208	    /**
209	     * The owner's age band, derived from the {@link #getBirthDate() birth date} as at the owner's
210	     * {@link #getRegistrationDate() registration date}: {@code 'MINOR'} when under 18, {@code 'ADULT'}
211	     * when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is the number of whole years
212	     * elapsed from the birth date to the registration date (defaulting to the server's current date
213	     * when no registration date is set yet). Returns {@code null} when no birth date was supplied.
214	     *
215	     * @return the age band, or {@code null} when the birth date is absent
216	     */
217	    public String getAgeBand() {
218	        if (this.birthDate == null) {
219	            return null;
220	        }
221	        LocalDate asAt = this.registrationDate != null ? this.registrationDate : LocalDate.now();
222	        int years = Period.between(this.birthDate, asAt).getYears();
223	        if (years < 18) {
224	            return "MINOR";
225	        }
226	        if (years < 65) {
227	            return "ADULT";
228	        }
229	        return "SENIOR";
230	    }
231	
232	    public String getCustomerCode() {
233	        return this.customerCode;
234	    }
235	
236	    public void setCustomerCode(String customerCode) {
237	        this.customerCode = customerCode;
238	    }
239	
240	    /**
241	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
242	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
243	     * from the owner's own customer code and registration date; {@code null} when either is absent.
244	     *
245	     * @return the membership number, or {@code null} when it cannot be derived
246	     */
247	    public String getMembershipNumber() {
248	        if (this.customerCode == null || this.registrationDate == null) {
249	            return null;
250	        }
251	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
252	    }
253	
254	    /**
255	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
256	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
257	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
258	     *
259	     * @return the Luhn check digit, or {@code null} when the customer code is absent
260	     */
261	    public Integer getCheckDigit() {
262	        if (this.customerCode == null) {
263	            return null;
264	        }
265	        int sum = 0;
266	        boolean dbl = true;
267	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
268	            char c = this.customerCode.charAt(i);
269	            if (c < '0' || c > '9') {
270	                continue;
271	            }
272	            int d = c - '0';
273	            if (dbl) {
274	                d *= 2;
275	                if (d > 9) {
276	                    d -= 9;
277	                }
278	            }
279	            sum += d;
280	            dbl = !dbl;
281	        }
282	        return (10 - (sum % 10)) % 10;
283	    }
284	
285	    /**
286	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
287	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
288	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
289	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure exceeds 365 days (see
290	     * {@link #getTenureDays()}). Because a newly created owner has zero tenure, the tenure points are
291	     * never awarded at create time.
292	     *
293	     * @return the membership points, a non-negative integer
294	     */
295	    public Integer getMembershipPoints() {
296	        int points = 0;
297	        boolean hasEmail = this.email != null && !this.email.isBlank();
298	        if (hasEmail) {
299	            points += 2;
300	        }
301	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
302	        if (hasNoNamesakes) {
303	            points += 1;
304	        }
305	        if (this.householdSize != null && this.householdSize >= 3) {
306	            points += 2;
307	        }
308	        Long tenureDays = getTenureDays();
309	        if (tenureDays != null && tenureDays > 365) {
310	            points += 3;
311	        }
312	        return points;
313	    }
314	
315	    /**
316	     * The owner's numeric membership level, mapped from the {@link #getMembershipPoints() membership
317	     * points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
318	     * for 6 or more points.
319	     *
320	     * @return the membership level, an integer from 1 to 4
321	     */
322	    public Integer getMembershipLevel() {
323	        int points = getMembershipPoints();
324	        if (points <= 1) {
325	            return 1;
326	        }
327	        if (points <= 3) {
328	            return 2;
329	        }
330	        if (points <= 5) {
331	            return 3;
332	        }
333	        return 4;
334	    }
335	
336	    /**
337	     * The owner's tenure in whole days, the number of days elapsed from the
338	     * {@link #getRegistrationDate() registration date} to the server's current date. A tenure of more
339	     * than 365 days is what raises the {@link #getMembershipLevel() membership level} to 4. Returns
340	     * {@code null} when no registration date has been set yet.
341	     *
342	     * @return the tenure in whole days, or {@code null} when the registration date is absent
343	     */
344	    public Long getTenureDays() {
345	        if (this.registrationDate == null) {
346	            return null;
347	        }
348	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
349	    }
350	
351	    /**
352	     * The owner's locality, the canonical region string. Once the owner has a
353	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
354	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
355	     * source of truth. Before the customer code is assigned (for example while a create is still
356	     * validating the postcode) it falls back to the region the code will be built from: the
357	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
358	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
359	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
360	     *
361	     * @return the canonical region string, or {@code 'UNKNOWN'}
362	     */
363	    public String getLocality() {
364	        if (this.customerCode != null) {
365	            int dash = this.customerCode.indexOf('-');
366	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
367	        }
368	        return deriveRegion();
369	    }
370	
371	    /**
372	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
373	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
374	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
375	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
376	     * the same region for known cities but disambiguates cities that share a name.
377	     *
378	     * @return the canonical region string, or {@code 'UNKNOWN'}
379	     */
380	    private String deriveRegion() {
381	        String region = regionFromPostcode();
382	        if (region != null) {
383	            return region;
384	        }
385	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
386	    }
387	
388	    /**
389	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
390	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
391	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
392	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
393	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
394	     * owner's region, telephone and last name. Call this once at create time and store the result via
395	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
396	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
397	     *
398	     * @return the assembled customer code
399	     */
400	    public String buildCustomerCode() {
401	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
402	    }
403	
404	    /**
405	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
406	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
407	     *
408	     * @param value the value to hash
409	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
410	     */
411	    private static String sha256Hex8(String value) {
412	        try {
413	            byte[] digest = MessageDigest.getInstance("SHA-256")
414	                .digest(value.getBytes(StandardCharsets.UTF_8));
415	            StringBuilder hex = new StringBuilder(8);
416	            for (int i = 0; i < 4; i++) {
417	                hex.append(String.format("%02X", digest[i]));
418	            }
419	            return hex.toString();
420	        }
421	        catch (NoSuchAlgorithmException e) {
422	            throw new IllegalStateException("SHA-256 algorithm not available", e);
423	        }
424	    }
425	
426	    /**
427	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
428	     * absent, not a 4-digit number, or in no known range.
429	     *
430	     * @return the matching region, or {@code null}
431	     */
432	    private String regionFromPostcode() {
433	        if (this.postcode == null) {
434	            return null;
435	        }
436	        int value;
437	        try {
438	            value = Integer.parseInt(this.postcode.trim());
439	        }
440	        catch (NumberFormatException ex) {
441	            return null;
442	        }
443	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
444	            int[] range = entry.getValue();
445	            if (value >= range[0] && value <= range[1]) {
446	                return entry.getKey();
447	            }
448	        }
449	        return null;
450	    }
451	
452	    /**
453	     * The owner's preferred contact channel, derived from the owner's details. Returns
454	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
455	     *
456	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
457	     */
458	    public String getContactPreference() {
459	        boolean hasEmail = this.email != null && !this.email.isBlank();
460	        return hasEmail ? "EMAIL" : "PHONE";
461	    }
462	
463	    /**
464	     * The owner's identity key, the single derived value used for duplicate detection. It is the
465	     * owner's normalized telephone, email (empty when absent) and household id joined with
466	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
467	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
468	     * are equal, so two members of the same household with different telephones differ here and are
469	     * both allowed.
470	     *
471	     * @return the derived identity key
472	     */
473	    public String getIdentityKey() {
474	        return (this.telephone == null ? "" : this.telephone) + "|"
475	            + (this.email == null ? "" : this.email) + "|"
476	            + (this.householdId == null ? "" : this.householdId);
477	    }
478	
479	    public String getHouseholdId() {
480	        return this.householdId;
481	    }
482	
483	    public void setHouseholdId(String householdId) {
484	        this.householdId = householdId;
485	    }
