527	    public Integer getPossibleDuplicateOf() {
528	        return this.possibleDuplicateOf;
529	    }
530	
531	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
532	        this.possibleDuplicateOf = possibleDuplicateOf;
533	    }
534	
535	    /**
536	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
537	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
538	     */
539	    @PrePersist
540	    void onCreate() {
541	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
542	    }
543	
544	    /**
545	     * Resolves the effective registration date and rolls it onto a business day. An absent
546	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
547	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
548	     * becomes the following Monday, while any weekday is returned unchanged.
549	     *
550	     * <p>This is the single definition of both the defaulting and the business-day roll, used
551	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
552	     * stamps the owner and by the create endpoint that counts owners per business day.
553	     *
554	     * @param supplied the registration date from the request, or {@code null} when none was supplied
555	     * @return the effective registration date, guaranteed to fall on a business day
556	     */
557	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
558	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
559	        return switch (effective.getDayOfWeek()) {
560	            case SATURDAY -> effective.plusDays(2);
561	            case SUNDAY -> effective.plusDays(1);
562	            default -> effective;
563	        };
564	    }
565	
566	    protected Set<Pet> getPetsInternal() {
567	        if (this.pets == null) {
568	            this.pets = new HashSet<>();
569	        }
570	        return this.pets;
571	    }
572	
573	    protected void setPetsInternal(Set<Pet> pets) {
574	        this.pets = pets;
575	    }
576	
577	    public List<Pet> getPets() {
578	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
579	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
580	        return Collections.unmodifiableList(sortedPets);
581	    }
582	
583	    public void setPets(List<Pet> pets) {
584	        this.pets = new HashSet<>(pets);
585	    }
586	
587	    public void addPet(Pet pet) {
588	        getPetsInternal().add(pet);
589	        pet.setOwner(this);
590	    }
591	
592	    /**
593	     * Return the Pet with the given name, or null if none found for this Owner.
594	     *
595	     * @param name to test
596	     * @return true if pet name is already in use
597	     */
598	    public Pet getPet(String name) {
599	        return getPet(name, false);
600	    }
601	
602	    /**
603	     * Return the Pet with the given name, or null if none found for this Owner.
604	     *
605	     * @param name to test
606	     * @return true if pet name is already in use
607	     */
608	    public Pet getPet(String name, boolean ignoreNew) {
609	        name = name.toLowerCase();
610	        for (Pet pet : getPetsInternal()) {
611	            if (!ignoreNew || !pet.isNew()) {
612	                String compName = pet.getName();
613	                compName = compName.toLowerCase();
614	                if (compName.equals(name)) {
615	                    return pet;
616	                }
617	            }
618	        }
619	        return null;
620	    }
621	
622	    public Pet getPet(Integer petId) {
623	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
624	    }
625	
626	    @Override
627	    public String toString() {
628	        return new ToStringCreator(this)
629	
630	            .append("id", this.getId())
631	            .append("new", this.isNew())
632	            .append("lastName", this.getLastName())
633	            .append("firstName", this.getFirstName())
634	            .append("address", this.address)
635	            .append("city", this.city)
636	            .append("telephone", this.telephone)
637	            .toString();
638	    }
639	}
